parameters.text:
=Analyze the following HTML content from a Dutch GP practice (huisartsenpraktijk) website and extract:

1. All doctor names working at this practice
2. Email addresses (practice email and individual doctor emails if available)
3. Phone numbers (main practice number and direct lines if available)
4. Full address details (street, number, postal code, city)
5. Specializations or additional information about each doctor

HTML Content:
{{ $json.data }}

Practice Info from Google:
- Name: {{ $('Get Place Details').item.json.result.name }}
- Address: {{ $('Get Place Details').item.json.result.formatted_address }}
- Phone: {{ $('Get Place Details').item.json.result.formatted_phone_number }}

Return the data in the following JSON structure:
{
  "practice_info": {
    "name": "practice name",
    "address": "full address",
    "postal_code": "postal code",
    "city": "city name",
    "phone": "phone number",
    "email": "practice email"
  },
  "doctors": [
    {
      "name": "doctor name",
      "email": "doctor email (if available)",
      "phone": "direct phone (if available)",
      "specialization": "specialization (if available)"
    }
  ]
}

parameters.jsCode:
// Parse AI response and structure the data
const items = [];

for (const item of $input.all()) {
  try {
    // Parse AI response
    let extractedData;
    if (typeof item.json.response === 'string') {
      // Try to find JSON in the response
      const jsonMatch = item.json.response.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        extractedData = JSON.parse(jsonMatch[0]);
      }
    } else {
      extractedData = item.json.response;
    }

    if (extractedData && extractedData.practice_info) {
      // Create main practice record
      const practiceRecord = {
        practice_name: extractedData.practice_info.name,
        address: extractedData.practice_info.address,
        postal_code: extractedData.practice_info.postal_code,
        city: extractedData.practice_info.city,
        phone: extractedData.practice_info.phone,
        email: extractedData.practice_info.email,
        website: item.json.website || '',
        doctors_count: extractedData.doctors ? extractedData.doctors.length : 0,
        scraped_date: new Date().toISOString()
      };

      items.push({ json: practiceRecord, pairedItem: { item: 0 } });

      // Create doctor records
      if (extractedData.doctors && Array.isArray(extractedData.doctors)) {
        for (const doctor of extractedData.doctors) {
          const doctorRecord = {
            practice_name: extractedData.practice_info.name,
            practice_city: extractedData.practice_info.city,
            doctor_name: doctor.name,
            doctor_email: doctor.email || '',
            doctor_phone: doctor.phone || '',
            specialization: doctor.specialization || '',
            scraped_date: new Date().toISOString()
          };
          items.push({ json: doctorRecord, pairedItem: { item: 0 } });
        }
      }
    }
  } catch (error) {
    console.error('Error parsing data:', error);
    // Still push the item with error info
    items.push({ 
      json: { 
        error: error.message,
        raw_data: item.json 
      }, 
      pairedItem: { item: 0 } 
    });
  }
}

return items;

// Add delay between requests to respect rate limits
const delayMs = 2000; // 2 seconds
await new Promise(resolve => setTimeout(resolve, delayMs));
return $input.all();
